package mrpapermoon.whisper.contacts.utilsimport mrpapermoon.whisper.contacts.db.ContactEntityimport mrpapermoon.whisper.entity.UserColorimport mrpapermoon.whisper.entity.UserIconobject UserGenerator {	fun createRandomContact(whispererId: String, name: String): ContactEntity {		return ContactEntity(			whispererId = whispererId,			name = name,			color = UserColor.random(),			icon = UserIcon.entries.random(),		)	}}